using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class F1WildRefine {
 const string E="Assets/Afrer_Seconds/05.Model/Environment/1F/";static string Root=>Path.GetFullPath(Application.dataPath+"/../../..");
 public static object Run(){var scene=SceneManager.GetActiveScene();if(scene.isDirty||Application.isPlaying||!scene.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");File.Copy(Root+"/SourceAssets/F1_WildernessDetail/WDNaturalSurface.hlsl",E+"WDNaturalSurface.hlsl",true);AssetDatabase.ImportAsset(E+"WDNaturalSurface.hlsl",ImportAssetOptions.ForceSynchronousImport|ImportAssetOptions.ForceUpdate);var records=new List<object>();foreach(var q in JArray.Parse(File.ReadAllText(Root+"/SourceAssets/F1_WildernessDetail/approach_models.json"))){string name=(string)q["name"],target=(string)q["target"],path=E+name+".fbx";var go=GameObject.Find(target);if(!go)throw new Exception("Missing approach target "+target);File.Copy(Path.Combine(Path.GetTempPath(),"AfterSeconds_WildernessDetail_20261113/candidate/"+name+".fbx"),path,true);AssetDatabase.ImportAsset(path,ImportAssetOptions.ForceSynchronousImport);var im=(ModelImporter)AssetImporter.GetAtPath(path);im.importAnimation=false;im.importCameras=false;im.importLights=false;im.isReadable=false;foreach(string n in q["materials"].Values<string>())im.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),n),AssetDatabase.LoadAssetAtPath<Material>(E+"Materials/"+n+".mat"));im.SaveAndReimport();var sources=AssetDatabase.LoadAssetAtPath<GameObject>(path).GetComponentsInChildren<MeshFilter>().OrderBy(f=>f.name).ToArray();var dest=go.GetComponentsInChildren<MeshFilter>().OrderBy(f=>f.name).ToArray();if(sources.Length!=dest.Length||sources.Length!=3)throw new Exception("LOD mismatch "+target);for(int i=0;i<3;i++){dest[i].sharedMesh=sources[i].sharedMesh;dest[i].GetComponent<Renderer>().sharedMaterials=sources[i].GetComponent<Renderer>().sharedMaterials;PrefabUtility.RecordPrefabInstancePropertyModifications(dest[i]);PrefabUtility.RecordPrefabInstancePropertyModifications(dest[i].GetComponent<Renderer>());}go.GetComponent<LODGroup>().RecalculateBounds();records.Add(new{target,asset=path,plants=(int)q["plants"]});}
 var near=GameObject.Find("AE_OvergrownFactoryTerrain").GetComponent<Terrain>();var mid=GameObject.Find("FW_WildernessTerrain").GetComponent<Terrain>();int aligned=0;var parent=GameObject.Find("WildernessEnding").transform;foreach(var group in new[]{parent.Find("DryScrubAndStone"),parent.Find("WildernessGroundDetail")})foreach(Transform t in group){if(t.name.Contains("Rock"))continue;var p=t.position;var terrain=p.x>=-192&&p.x<=192&&p.z>=-160&&p.z<=160?near:mid;var n=terrain.terrainData.GetInterpolatedNormal((p.x-terrain.transform.position.x)/terrain.terrainData.size.x,(p.z-terrain.transform.position.z)/terrain.terrainData.size.z);float yaw=t.eulerAngles.y;t.rotation=Quaternion.FromToRotation(Vector3.up,n)*Quaternion.Euler(0,yaw,0);if(PrefabUtility.IsPartOfPrefabInstance(t))PrefabUtility.RecordPrefabInstancePropertyModifications(t);aligned++;}
 AssetDatabase.SaveAssets();Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);File.WriteAllText(Root+"/Docs/Review/2026-11-13_1F_WildernessDetail/approach.json",JsonConvert.SerializeObject(records,Formatting.Indented));return new{approachChunks=records.Count,slopeAligned=aligned,saved=true};}
}
